const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Polygon([[
    [33.4339, 46.7725], [33.7299, 46.7725],
    [33.7299, 46.6111], [33.4339, 46.6111],
    [33.4339, 46.7725]
  ]]);

  const date1 = '2023-05-17';
  const date2 = '2023-06-18';
  const dateRangeBuffer = 2; // Days to buffer for finding a clear image

  // 2. Data Acquisition & Processing Function
  function getSentinelImage(date) {
    const startDate = ee.Date(date).advance(-dateRangeBuffer, 'day');
    const endDate = ee.Date(date).advance(dateRangeBuffer, 'day');

    const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(aoi)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

    // If no images found, return null
    if (collection.size().getInfo() === 0) {
      return null;
    }

    const image = ee.Image(collection.sort('CLOUDY_PIXEL_PERCENTAGE').first());

    // Mask clouds and non-vegetation using Scene Classification Layer (SCL)
    // Values 4 (vegetation) and 5 (not vegetated/bare soil) are relevant for agricultural fields.
    const scl = image.select('SCL');
    const mask = scl.eq(4).or(scl.eq(5)); // Keep vegetation and bare soil (cropland)

    return image.updateMask(mask).divide(10000).select(['B4', 'B8']);
  }

  // 3. Calculation
  const imageMay = getSentinelImage(date1);
  const imageJune = getSentinelImage(date2);

  if (!imageMay || !imageJune) {
    console.log(`Image found for May 2023: ${!!imageMay}`);
    console.log(`Image found for June 2023: ${!!imageJune}`);
    console.log("Could not find a low-cloud image for one or both dates.");
    console.log("C1");
    return;
  }

  const ndviMay = imageMay.normalizedDifference(['B8', 'B4']);
  const ndviJune = imageJune.normalizedDifference(['B8', 'B4']);

  const commonReducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const statsMay = ndviMay.reduceRegion({
    reducer: commonReducer,
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  });

  const statsJune = ndviJune.reduceRegion({
    reducer: commonReducer,
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  });

  const meanMay = statsMay.get('nd_mean').getInfo();
  const pixelsMay = statsMay.get('nd_count').getInfo();

  const meanJune = statsJune.get('nd_mean').getInfo();
  const pixelsJune = statsJune.get('nd_count').getInfo();


  // 4. Validation & Final Answer
  if (pixelsMay === 0 || pixelsJune === 0) {
      console.log(`Valid pixels in May: ${pixelsMay}`);
      console.log(`Valid pixels in June: ${pixelsJune}`);
      console.log("No valid pixels found after cloud/data masking.");
      console.log("C2");
      return;
  }

  if (meanMay === null || meanJune === null) {
      console.log(`May NDVI calculation result: ${meanMay}`);
      console.log(`June NDVI calculation result: ${meanJune}`);
      console.log("NDVI calculation failed or returned null.");
      console.log("C3");
      return;
  }

  console.log(`May 17, 2023 - Mean NDVI: ${meanMay.toFixed(4)}, Valid Pixels: ${pixelsMay}`);
  console.log(`June 18, 2023 - Mean NDVI: ${meanJune.toFixed(4)}, Valid Pixels: ${pixelsJune}`);

  // "Browner" means less green, which corresponds to a lower NDVI.
  if (meanJune < meanMay) {
    console.log("Fields were browner in June (lower NDVI).");
    console.log("A");
  } else {
    console.log("Fields were not browner in June (higher or equal NDVI).");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
